# area: context_managers
# hypothesis: A context manager whose __exit__ is annotated to return bool swallows the exception, so checkers must treat the code after the with-block as reachable, while a __exit__ returning None lets the exception propagate.
from typing import Self, reveal_type
from types import TracebackType


class Swallow:
    def __enter__(self) -> Self:
        return self

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        tb: TracebackType | None,
    ) -> bool:
        return True


class Passthrough:
    def __enter__(self) -> int:
        return 7

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        tb: TracebackType | None,
    ) -> None:
        return None


def run_swallow() -> str:
    with Swallow() as s:
        reveal_type(s)
        raise ValueError('boom')
    return 'after swallow'


def run_passthrough() -> str:
    try:
        with Passthrough() as n:
            reveal_type(n)
            raise KeyError('k')
    except KeyError:
        return 'propagated'
    return 'unreachable'


print(run_swallow())
print(run_passthrough())
